# input shape dimensions 9x10; coordinates relative 0-based. output 10x9.
transforms={
'cw':lambda r,c:(c,8-r),
'ccw':lambda r,c:(9-c,r),
'180':lambda r,c:(8-r,9-c),
'transpose':lambda r,c:(c,r),
'anti-transpose':lambda r,c:(9-c,8-r),
'flipH':lambda r,c:(r,9-c),
'flipV':lambda r,c:(8-r,c),
}
for n,f in transforms.items():
